/** Input archives are restricted to the private synthetic imports directory. No URL or public upload. */
function clubMigrationStageFile(PDO $pdo,string $path,int $actor):int {
 clubMigrationGuard($pdo);$base=realpath(getenv('LOCALAPPDATA').'/EvidencePavelB1/finance-b1-20261022/private/imports');$real=realpath($path);
 if(!$base||!$real||!str_starts_with(strtolower(str_replace('\\','/',$real)),strtolower(str_replace('\\','/',$base)).'/')||!is_file($real)||filesize($real)>12000000)throw new DomainException('Soubor musí být v soukromé složce syntetických importů a do 12 MB.');clubMigrationActor($pdo,$actor);$bytes=(string)file_get_contents($real);$payload=json_decode($bytes,true,64,JSON_THROW_ON_ERROR);if(($payload['synthetic_only']??false)!==true)throw new DomainException('Povoleny jsou pouze syntetické zdroje.');$sha=hash('sha256',$bytes);$archive=$base.'/archive';if(!is_dir($archive)&&!mkdir($archive,0700,true))throw new DomainException('Archiv nelze připravit.');$resolved=realpath($archive);if(!$resolved||!str_starts_with(strtolower(str_replace('\\','/',$resolved)),strtolower(str_replace('\\','/',$base)).'/'))throw new DomainException('Archiv není v soukromém úložišti.');$destination=$resolved.'/'.$sha.'.json';$f=@fopen($destination,'xb');if(is_resource($f)){try{if(fwrite($f,$bytes)!==strlen($bytes))throw new DomainException('Originál se nepodařilo archivovat.');fflush($f);}finally{fclose($f);}}if(!is_file($destination)||!hash_equals($sha,(string)hash_file('sha256',$destination)))throw new DomainException('Neměnný archiv již obsahuje jiný obsah.');return clubMigrationStage($pdo,$payload,$actor,['name'=>basename($real),'size'=>strlen($bytes),'sha256'=>$sha,'archive_key'=>'imports/archive/'.$sha.'.json']);
