function clubMigrationStage(PDO $pdo,array $payload,int $actor,array $file=[]):int {
 if(($payload['contract']??'')!=='club-migration.synthetic.v1'||($payload['synthetic_only']??false)!==true)throw new DomainException('Povoleny jsou výhradně označené syntetické zkoušky.');if(($payload['timezone']??'')!=='Europe/Prague')throw new DomainException('Zdroj musí výslovně potvrdit časové pásmo Europe/Prague.');$namespace=clubMigrationKey((string)($payload['source_namespace']??''));$records=$payload['records']??null;if(!is_array($records)||count($records)>5000)throw new DomainException('Dávka musí obsahovat nejvýše 5000 položek.');
 foreach(['window_from','window_to'] as $k){$v=(string)($payload[$k]??'');$d=DateTimeImmutable::createFromFormat('!Y-m-d H:i:s',$v);if(!$d||$d->format('Y-m-d H:i:s')!==$v)throw new DomainException('Doplňte přesný časový rozsah snímku.');}if($payload['window_from']>$payload['window_to'])throw new DomainException('Neplatný rozsah snímku.');
 $seen=[];foreach($records as $r){$type=clubMigrationKey((string)($r['type']??''));$id=clubMigrationKey((string)($r['source_id']??''));if(isset($seen[$type.':'.$id])||!is_array($r['data']??null))throw new DomainException('Dávka obsahuje duplicitní ID nebo neplatný obsah.');if(array_key_exists('_tombstone',$r['data']))throw new DomainException('Zdrojový obsah nesmí přepsat vyhrazený příznak výmazu.');$seen[$type.':'.$id]=true;}
 $hash=clubMigrationHash($payload);return clubMigrationTransaction($pdo,function()use($pdo,$payload,$actor,$file,$namespace,$records,$hash){clubMigrationActor($pdo,$actor);$q=$pdo->prepare('SELECT id FROM club_migration_batches WHERE source_namespace=? AND source_hash=?');$q->execute([$namespace,$hash]);if($id=$q->fetchColumn())return (int)$id;
  $manifest=['file'=>$file,'records'=>count($records),'source_window'=>[$payload['window_from'],$payload['window_to']],'timezone'=>$payload['timezone'],'synthetic_only'=>true,'source_hash'=>$hash,'source_payload'=>$payload,'converter'=>CLUB_MIGRATION_CONVERTER,'converter_sha256'=>clubMigrationCodeHash()];$pdo->prepare('INSERT INTO club_migration_batches(source_namespace,source_hash,contract,converter_version,source_window_from,source_window_to,manifest_json,created_by) VALUES(?,?,?,?,?,?,?,?)')->execute([$namespace,$hash,$payload['contract'],CLUB_MIGRATION_CONVERTER,$payload['window_from'],$payload['window_to'],clubMigrationJson($manifest),$actor]);$id=(int)$pdo->lastInsertId();
