}
function clubMigrationMap(PDO $pdo,string $namespace,string $type,string $sourceId):?array{$q=$pdo->prepare('SELECT * FROM club_migration_maps WHERE source_namespace=? AND entity_type=? AND source_id=?');$q->execute([$namespace,$type,$sourceId]);return $q->fetch(PDO::FETCH_ASSOC)?:null;}
/** Adapter preview/apply/target have explicit typed contracts, never arbitrary SQL from source. */
function clubMigrationReview(PDO $pdo,int $itemId,int $expectedRevision,string $decision,array $proposal,string $expectedSourceHash,int $actor,string $reason):array {
 $reason=accountingLedgerAudit($actor,$reason,true);if(!in_array($decision,['approve','quarantine','archive'],true))throw new DomainException('Neplatné rozhodnutí.');
 return clubMigrationTransaction($pdo,function()use($pdo,$itemId,$expectedRevision,$decision,$proposal,$expectedSourceHash,$actor,$reason){clubMigrationActor($pdo,$actor);$i=clubMigrationItem($pdo,$itemId);$b=clubMigrationBatch($pdo,(int)$i['batch_id']);if((int)$i['revision']!==$expectedRevision||!hash_equals($i['source_hash'],$expectedSourceHash)||in_array($i['state'],['applied','linked'],true))throw new DomainException('Zdroj nebo rozhodnutí se změnily, případně je položka již převzatá.');$data=json_decode($i['payload_json'],true,64,JSON_THROW_ON_ERROR);$preview=['target_type'=>null,'target_id'=>null,'target_hash'=>null,'issues'=>[]];
  clubMigrationVerifySource($b);clubMigrationVerifyItemSource($b,$i);
  if($decision==='archive'){($authorize=clubMigrationAdapter($i['entity_type'])['authorize'])($pdo,$actor);}
  if($decision==='approve'){
   if(!empty($data['_tombstone']))throw new DomainException('Výmaz nelze automaticky schválit k provedení.');$adapter=clubMigrationAdapter($i['entity_type']);($adapter['authorize'])($pdo,$actor);
   $map=clubMigrationMap($pdo,$b['source_namespace'],$i['entity_type'],$i['source_id']);if($map){if(!hash_equals($map['source_hash'],$i['source_hash']))throw new DomainException('Stejné zdrojové ID má jiný obsah; odložte rozdíl k posouzení.');$target=($adapter['target'])($pdo,$map['target_type'],(int)$map['target_id']);if(!hash_equals($map['target_hash'],clubMigrationHash($target)))throw new DomainException('Mapovaný cíl se změnil.');$preview=['target_type'=>$map['target_type'],'target_id'=>(int)$map['target_id'],'target_hash'=>$map['target_hash'],'issues'=>[]];}
   else{$preview=($adapter['preview'])($pdo,$b,$i,$data,$proposal);if($preview['issues']??[])throw new DomainException('Položka vyžaduje dořešení: '.implode('; ',$preview['issues']));}
  }
  $proposal['_converter_sha256']=clubMigrationCodeHash();$proposal['_approved_target']=array_intersect_key($preview,array_flip(['target_type','target_id','target_hash']));
  $reviewHash=clubMigrationHash([$i['source_hash'],$proposal,$preview,clubMigrationCodeHash()]);$state=match($decision){'approve'=>'approved','archive'=>'archived',default=>'quarantine'};
  $pdo->prepare('UPDATE club_migration_items SET state=?,decision=?,proposal_json=?,target_type=?,target_id=?,target_hash=?,review_hash=?,reason=?,revision=revision+1,reviewed_by=? WHERE id=?')->execute([$state,$decision,clubMigrationJson($proposal),$preview['target_type'],$preview['target_id'],$preview['target_hash'],$reviewHash,$reason,$actor,$itemId]);clubMigrationEvent($pdo,(int)$b['id'],$itemId,'reviewed',$actor,$reason,['revision'=>$expectedRevision+1,'decision'=>$decision,'review_hash'=>$reviewHash,'preview'=>$preview]);return clubMigrationItem($pdo,$itemId);
 });
}
function clubMigrationPlanHash(PDO $pdo,int $batch):string {$b=clubMigrationBatch($pdo,$batch);$q=$pdo->prepare('SELECT id,source_hash,review_hash,proposal_json,decision,revision FROM club_migration_items WHERE batch_id=? ORDER BY id');$q->execute([$batch]);return clubMigrationHash([$b['source_hash'],clubMigrationCodeHash(),$q->fetchAll(PDO::FETCH_ASSOC)]);}
/** One item is atomic. A stopped batch resumes with the same plan hash and stable provenance. */
function clubMigrationApply(PDO $pdo,int $batchId,string $expectedPlanHash,int $actor,int $limit=100):array {
 clubMigrationTransaction($pdo,function()use($pdo,$batchId,$expectedPlanHash,$actor){clubMigrationActor($pdo,$actor);clubMigrationVerifySource(clubMigrationBatch($pdo,$batchId));if(!hash_equals(clubMigrationPlanHash($pdo,$batchId),$expectedPlanHash))throw new DomainException('Náhled se změnil.');$q=$pdo->prepare("SELECT * FROM club_migration_items WHERE batch_id=? AND state IN ('applied','linked')");$q->execute([$batchId]);foreach($q->fetchAll(PDO::FETCH_ASSOC) as $i){$a=clubMigrationAdapter($i['entity_type']);$current=($a['target'])($pdo,$i['target_type'],(int)$i['target_id']);if(!hash_equals($i['target_hash'],clubMigrationHash($current)))throw new DomainException('Dříve převzatý cíl se změnil; opakování jej nepřepíše.');}});
 $limit=max(1,min(500,$limit));$q=$pdo->prepare("SELECT id FROM club_migration_items WHERE batch_id=? AND state='approved' ORDER BY id LIMIT ".$limit);$q->execute([$batchId]);$ids=$q->fetchAll(PDO::FETCH_COLUMN);
 foreach($ids as $id)clubMigrationTransaction($pdo,function()use($pdo,$batchId,$expectedPlanHash,$actor,$id){clubMigrationActor($pdo,$actor);if(!hash_equals(clubMigrationPlanHash($pdo,$batchId),$expectedPlanHash))throw new DomainException('Náhled se změnil; schválený otisk plánu již neplatí.');$i=clubMigrationItem($pdo,(int)$id);if(in_array($i['state'],['applied','linked'],true))return;if($i['state']!=='approved')throw new DomainException('Položka není schválena.');$b=clubMigrationBatch($pdo,$batchId);clubMigrationVerifySource($b);$data=json_decode($i['payload_json'],true,64,JSON_THROW_ON_ERROR);if(!hash_equals($i['source_hash'],clubMigrationHash($data)))throw new DomainException('Obsah stagingu se změnil.');$proposal=json_decode($i['proposal_json'],true,64,JSON_THROW_ON_ERROR);$adapter=clubMigrationAdapter($i['entity_type']);($adapter['authorize'])($pdo,$actor);
  clubMigrationVerifyItemSource($b,$i);if(($proposal['_converter_sha256']??'')!==clubMigrationCodeHash())throw new DomainException('Převodník se od schválení změnil. Vyžaduje nové posouzení.');
  $map=clubMigrationMap($pdo,$b['source_namespace'],$i['entity_type'],$i['source_id']);
  if($map){if(!hash_equals($map['source_hash'],$i['source_hash']))throw new DomainException('Zdrojové ID se změnilo.');$approved=$proposal['_approved_target']??[];if((int)($approved['target_id']??0)>0){if($approved['target_type']!==$map['target_type']||(int)$approved['target_id']!==(int)$map['target_id']||$approved['target_hash']!==$map['target_hash'])throw new DomainException('Souběžně vzniklá mapa neodpovídá výslovně schválenému cíli.');}else{$origin=clubMigrationItem($pdo,(int)$map['item_id']);if($origin['review_hash']!==$i['review_hash'])throw new DomainException('Souběžně vzniklá mapa má jiné schválené podklady.');}$current=($adapter['target'])($pdo,$map['target_type'],(int)$map['target_id']);if(!hash_equals($map['target_hash'],clubMigrationHash($current)))throw new DomainException('Dříve převzatý cíl se změnil. Opakování jej nepřepíše.');$result=['target_type'=>$map['target_type'],'target_id'=>(int)$map['target_id']];$state='linked';}
  else{$preview=($adapter['preview'])($pdo,$b,$i,$data,$proposal);if(($preview['issues']??[])||!hash_equals($i['review_hash'],clubMigrationHash([$i['source_hash'],$proposal,$preview,clubMigrationCodeHash()])))throw new DomainException('Cílová data, mapy nebo převodník se od schválení změnily.');$result=($adapter['apply'])($pdo,$b,$i,$data,$proposal,$actor);$current=($adapter['target'])($pdo,$result['target_type'],(int)$result['target_id']);$state=($result['linked']??false)?'linked':'applied';$pdo->prepare('INSERT INTO club_migration_maps(source_namespace,entity_type,source_id,source_hash,target_type,target_id,target_hash,item_id) VALUES(?,?,?,?,?,?,?,?)')->execute([$b['source_namespace'],$i['entity_type'],$i['source_id'],$i['source_hash'],$result['target_type'],$result['target_id'],clubMigrationHash($current),$i['id']]);}
  $pdo->prepare('UPDATE club_migration_items SET state=?,target_type=?,target_id=?,target_hash=?,applied_at=CURRENT_TIMESTAMP WHERE id=?')->execute([$state,$result['target_type'],$result['target_id'],clubMigrationHash($current),$i['id']]);clubMigrationEvent($pdo,$batchId,(int)$i['id'],$state,$actor,'Syntetický aditivní převod; původní cílová data nepřepsána.',$result+['source_hash'=>$i['source_hash'],'target_hash'=>clubMigrationHash($current)]);
