function clubMigrationReport(PDO $pdo,int $batchId):array {
 $b=clubMigrationBatch($pdo,$batchId);$q=$pdo->prepare('SELECT id,entity_type,source_id,source_hash,target_type,target_id,target_hash,decision,state,reason,revision FROM club_migration_items WHERE batch_id=? ORDER BY id');$q->execute([$batchId]);$items=$q->fetchAll(PDO::FETCH_ASSOC);$counts=array_fill_keys(['pending','approved','quarantine','applied','linked','archived'],0);foreach($items as $i)$counts[$i['state']]++;$integrity=[];try{clubMigrationVerifySource($b);}catch(Throwable $e){$integrity[]='Zdrojový archiv nelze ověřit.';}foreach($items as $item)if(in_array($item['state'],['applied','linked'],true)){try{$a=clubMigrationAdapter($item['entity_type']);$actual=($a['target'])($pdo,$item['target_type'],(int)$item['target_id']);if(!hash_equals($item['target_hash'],clubMigrationHash($actual)))$integrity[]='Cíl položky #'.$item['id'].' se změnil.';}catch(Throwable){$integrity[]='Cíl položky #'.$item['id'].' nelze ověřit.';}}$state=$items&&!$integrity&&($counts['pending']+$counts['approved']+$counts['quarantine']+$counts['archived'])===0?'rehearsal_complete':'review_required';return ['id'=>$batchId,'source_namespace'=>$b['source_namespace'],'source_hash'=>$b['source_hash'],'plan_hash'=>clubMigrationPlanHash($pdo,$batchId),'state'=>$state,'counts'=>$counts,'items'=>$items,'integrity_issues'=>$integrity,'synthetic_only'=>true];
